import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.C_fNVUec.js";const r="/orc/screens/dashboard-light.png",n="/orc/screens/dashboard.png",d="/orc/screens/tasks.png",i="/orc/screens/task-detail.png",l="/orc/screens/task-flow.png",h="/orc/screens/sessions.png",c="/orc/screens/terminals.png",p="/orc/screens/knowledge.png",g="/orc/screens/jobs.png",u="/orc/screens/settings.png",P=JSON.parse('{"title":"Desktop app and web dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"docs/desktop-and-web.md","filePath":"docs/desktop-and-web.md","lastUpdated":1793898059000}'),m={name:"docs/desktop-and-web.md"};function b(k,t,f,w,y,S){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="desktop-app-and-web-dashboard" tabindex="-1">Desktop app and web dashboard <a class="header-anchor" href="#desktop-app-and-web-dashboard" aria-label="Permalink to &quot;Desktop app and web dashboard&quot;">​</a></h1><p>A tour of every page in the ORC dashboard and what the desktop app adds on top of it.</p><p>The dashboard is served by the daemon at <code>http://localhost:7700</code>. The desktop app shows the same dashboard in its own window, so everything below applies to both.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Contents</th></tr></thead><tbody><tr><td>Sidebar</td><td>Activity, Tasks, Knowledge, Terminals, Library, Settings. Shows the execution host, for example <code>Connected (local)</code>.</td></tr><tr><td>Project picker</td><td>Scopes most pages to one project, all projects, or unassigned items</td></tr><tr><td>Chat panel</td><td>Talk to Claude, Codex or an ACPX agent from any page. Pick the agent and model at the top.</td></tr><tr><td>Command palette</td><td><strong>Ctrl+K</strong> (<strong>Cmd+K</strong> on macOS) to search and run commands</td></tr></tbody></table><p>Pages are grouped in the sidebar:</p><table tabindex="0"><thead><tr><th>Group</th><th>Pages</th></tr></thead><tbody><tr><td>Activity</td><td>Activity, Attention needed, Sessions, Jobs, Webhooks, Audit</td></tr><tr><td>Tasks</td><td>Tasks</td></tr><tr><td>Knowledge</td><td>Knowledge base, Memories</td></tr><tr><td>Terminals</td><td>Terminals</td></tr><tr><td>Library</td><td>Skills, Packages, Agents, Rules, Scratchpads</td></tr><tr><td>Settings</td><td>Settings</td></tr></tbody></table><p>Projects has its own page at <code>/projects</code>. Every page has a shareable URL.</p><p>The sun and moon button in the header switches between the dark and light themes:</p><p><img src="'+r+'" alt="Dashboard in the light theme"></p><h2 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h2><p><img src="'+n+'" alt="Activity"></p><p>The <strong>Activity</strong> page: task metrics plus recent jobs, memories and sessions for the selected project.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p><img src="'+d+'" alt="Tasks"></p><p>The task board. Switch between <strong>Board</strong> (kanban) and <strong>Table</strong> views and filter the list. The GitHub panel lists issues and pull requests from known repositories (yours, assigned to you, or all open) and links them to tasks.</p><p>Open a task to see its body, status, comments, linked sessions and Git links, and its flow run:</p><p><img src="'+i+'" alt="Task detail"></p><p><strong>Edit task → View flow</strong> shows the nodes and edges of the task&#39;s <a href="./task-flows">flow</a>, including loops back for review:</p><p><img src="'+l+'" alt="Task flow"></p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p><img src="'+h+'" alt="Sessions"></p><p>Live and archived sessions from Claude Code, Codex, Cursor and Gemini on this machine or the selected host. Working sessions update live; waiting sessions stay available to resume in a terminal or in chat. Search across archived conversations. See <a href="./live-sessions">Live sessions</a>.</p><h2 id="terminals" tabindex="-1">Terminals <a class="header-anchor" href="#terminals" aria-label="Permalink to &quot;Terminals&quot;">​</a></h2><p><img src="'+c+'" alt="Terminals"></p><p>Browser terminals for shells and coding agents, with split panes and Files and Git panels beside them. Terminals run on the selected execution host. See <a href="./terminal-workspace">Terminal workspace</a>.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Create, edit and archive projects. A project has a name, description, tags and an optional Git remote URL. Deleting a project deletes its memories and scratchpads and keeps its tasks, jobs and sessions without a project.</p><h2 id="memories" tabindex="-1">Memories <a class="header-anchor" href="#memories" aria-label="Permalink to &quot;Memories&quot;">​</a></h2><p>Short project facts (ports, conventions, decisions) that agents load at session start. Create, edit, and view each memory&#39;s change history. Under <strong>Knowledge → Memories</strong>.</p><h2 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h2><p><img src="'+p+'" alt="Knowledge"></p><p>Knowledge bases: upload PDFs, Office files, HTML, CSV and Markdown, write Markdown in place, or register a folder to copy in. Search returns cited passages. Each knowledge base can have a digest agent that maintains it on a schedule.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p><img src="'+g+'" alt="Jobs"></p><p>Scheduled and on-demand automation. A job runs a shell command, an agent or creates a task, triggered manually, by cron, by a file watch, once, or by a webhook. Each job keeps its run history with logs and linked agent sessions.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>Inbound event sources. Configure a webhook once, then connect it to one or more jobs, each with its own event filters and action.</p><h2 id="attention-needed" tabindex="-1">Attention needed <a class="header-anchor" href="#attention-needed" aria-label="Permalink to &quot;Attention needed&quot;">​</a></h2><p>Questions and approval requests from your agents in one queue. Answer here and the reply goes back to the waiting session. See <a href="./human-requests">Human requests</a>.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Recorded session summaries and events. Use Sessions to read full conversations or resume an agent.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Reusable agent instructions stored as skill folders. Import skills from a repository or from local agent folders, create your own, edit files, view history, and assign skills to projects. See <a href="./skills">Skills</a>.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>Packages bundle instructions, skills and tools for reuse. Launch a package in chat or a terminal on the host and folder you choose. See <a href="./agent-packages">Agent packages</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>Shared specialist agent definitions: instructions, model and tools, reusable across coding agents and packable into packages. Under <strong>Library → Agents</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>Applied rules and their outcomes per workspace, plus rule settings for enforcement and agent assignment. See <a href="./agent-rules">Agent rules</a>.</p><h2 id="scratchpads" tabindex="-1">Scratchpads <a class="header-anchor" href="#scratchpads" aria-label="Permalink to &quot;Scratchpads&quot;">​</a></h2><p>Working documents, diagrams and HTML pages that you or an agent create and come back to. Agents use the <code>pad_*</code> MCP tools. Share one by copying its link.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+u+'" alt="Settings"></p><table tabindex="0"><thead><tr><th>Section</th><th>Controls</th></tr></thead><tbody><tr><td>Connection</td><td>API URL for this browser</td></tr><tr><td>Security</td><td>Sign-in status and sign-out, default sign-in lifetime, allowed web origins, access tokens (minted by entering the secret)</td></tr><tr><td>Appearance</td><td>Theme</td></tr><tr><td>Execution host</td><td>Run agents, terminals and git locally or on an SSH host from <code>~/.ssh/config</code></td></tr><tr><td>Server</td><td><strong>Restart ORC server</strong> (closes terminals, keeps settings, reconnects)</td></tr><tr><td>Notifications</td><td>Browser push notifications for approvals, questions and chat replies. Needs HTTPS.</td></tr><tr><td>Channels</td><td>Telegram and Slack connections</td></tr><tr><td>Chat</td><td>Default models, instructions, tools and permission mode for chat</td></tr><tr><td>MCP</td><td>Build the MCP config snippet for your agent. See <a href="./connect-agents">Connect agents</a>.</td></tr><tr><td>Integrations</td><td>APIs and MCP servers in the <code>spec</code> CLI registry</td></tr><tr><td>Knowledge</td><td>Parser, embeddings and knowledge defaults</td></tr><tr><td>Terminals</td><td>Terminal font for new terminals</td></tr><tr><td>Storage</td><td>Where settings are stored</td></tr></tbody></table><h2 id="desktop-app-only" tabindex="-1">Desktop app only <a class="header-anchor" href="#desktop-app-only" aria-label="Permalink to &quot;Desktop app only&quot;">​</a></h2><p>The desktop app is an Electron shell around the same dashboard. On top of the browser experience it:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Detail</th></tr></thead><tbody><tr><td>Runs the daemon for you</td><td>Starts the bundled <code>orc</code> daemon, or attaches to one already running on the configured port</td></tr><tr><td>Configures auth</td><td>Generates an API secret when none is set and sends it on every request. No sign-in screen.</td></tr><tr><td>Installs the CLI</td><td><code>~/.orc/bin/orc</code>, added to your shell <code>PATH</code></td></tr><tr><td>Tray icon</td><td><strong>Open orc</strong>, <strong>Start at login</strong> toggle, <strong>Quit orc</strong></td></tr><tr><td>Start at login</td><td>On by default, starts hidden in the tray</td></tr><tr><td>Keeps running when closed</td><td>On Windows and Linux, closing the window hides it; the daemon keeps running. On macOS, closing the window currently quits the app (<a href="https://github.com/niradler/orc/issues/176" target="_blank" rel="noreferrer">#176</a>).</td></tr><tr><td>Recovers from crashes</td><td>If the daemon stops, offers <strong>Retry</strong> or <strong>Quit</strong></td></tr><tr><td>Remembers the window</td><td>Size, position and maximized state</td></tr></tbody></table><p>Quitting the app (<strong>Quit orc</strong>) stops the daemon only if the app started it.</p><p>Command-line flags for the app executable:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--hidden</code></td><td>Start without opening a window</td></tr><tr><td><code>--quit</code></td><td>Quit the running instance and the daemon it started</td></tr></tbody></table><p>Links to other sites open in your system browser. The app has no auto-update; see <a href="./install#upgrading">Upgrading</a>.</p>',62)])])}const _=e(m,[["render",b]]);export{P as __pageData,_ as default};
